     값이아닌주소값의비교(값을비교하고싶다면역참조후비교)


    string s1="Frank";                           string s1="Hyungki";
    string s2="Hyungki“;                         string s2="Hyungki";

    string* p1 =&s1;                             string* p1 =&s1;
    string* p2 =&s2;                             string* p2 =&s2;
    string* p3 =&s1;                             string* p3 =&s1;

    cout << (p1==p2) << endl; // false           cout << (*p1==*p2) << endl; // true
    cout << (p1==p3) << endl; //true             cout << (*p1==*p3) << endl; // true

